import{_ as t}from"./chunks/edit-event-low-key-event.CZX-AdEE.js";import{c as n,Q as o,j as r,m as a}from"./chunks/framework.BqPkuuVc.js";const s="/assets/edit-event-low-key-event-scrolled.4Z_HsKXZ.png",i="/assets/docs-setup-event-quick-name-entry.C5lr8Q4j.png",d="/assets/docs-setup-event-quick-name-entry-tile.BZ_yfFC4.png",y=JSON.parse('{"title":"Low-key events","description":"","frontmatter":{},"headers":[],"relativePath":"user/event-setup/low-key-events.md","filePath":"user/event-setup/low-key-events.md"}'),h={name:"user/event-setup/low-key-events.md"};function c(l,e,u,g,m,p){return o(),r("div",null,[...e[0]||(e[0]=[a('<h1 id="low-key-events" tabindex="-1">Low-key events <a class="header-anchor" href="#low-key-events" aria-label="Permalink to &quot;Low-key events&quot;">​</a></h1><p><strong>Audience:</strong> Organisers of club trainings, come-and-try days and other events where nobody enters beforehand.</p><p>At a small event the runners turn up, borrow or bring a <a href="./../getting-started/concepts-glossary">card</a>, run one of a few courses put out that morning, and come back to download. There is no entry list to import and often no course file either. Six settings let Manager run such an event from the cards alone, with nothing to click at the download desk.</p><p>All six are on the <strong>Low-key event</strong> tab of <strong>Event details</strong> (the button at the top of the dashboard — see <a href="./create-event#editing-event-details">Editing event details</a>). Each switch has a line under it saying what it does. A new event starts with them as <strong>Settings → Low-key events</strong> has them — all off unless you have changed that page (see <a href="#making-them-the-default">Making them the default</a>).</p><p><img src="'+t+'" alt="The Low-key event tab: Auto create competitors on download, Auto create courses and classes, Ignore competitor registry, Ignore hire cards and Quick name entry on download, all off"></p><p>The tab is taller than the dialog; the last switch is further down.</p><p><img src="'+s+'" alt="The Low-key event tab scrolled to its end: Quick name entry on download and, below it, Add competitor on download of an unknown card, both off"></p><h2 id="auto-create-competitors-on-download" tabindex="-1">Auto create competitors on download <a class="header-anchor" href="#auto-create-competitors-on-download" aria-label="Permalink to &quot;Auto create competitors on download&quot;">​</a></h2><p>With this on, a downloaded card that nobody is entered on is entered as a new competitor straight away, and the download banner shows their result, time and place as it would for anyone entered beforehand. There is no <strong>Unassigned</strong> banner to deal with.</p><ul><li><strong>The name.</strong> If the card is in your <a href="./../reference/competitor-registry">competitor registry</a>, and only one person in it has that card, they are entered as that person (unless the event <a href="#ignore-competitor-registry">ignores the registry</a>). Otherwise their card number stands in for their name, and the banner shows a small <strong>+</strong> beside it — click it to open the competitor and type the name. Nobody has to: an unnamed runner still gets a result.</li><li><strong>The class.</strong> The class whose course the card fits — by the rule set out under <a href="#auto-create-courses-and-classes">What counts as fitting a course</a>, so a runner who missed a control on a long course is entered on that course with the mis-punch, never on a shorter course their card happens to contain. If no course fits, they are entered without a class and the banner says <strong>Not competing</strong> — except for another run on the same card, which keeps the person&#39;s earlier class. Give them a class and the card is checked again. A relay class is never chosen: a card cannot say which team and leg.</li><li><strong>Several runs on one card.</strong> Everywhere else a later run on a card belongs to nobody until you say who ran it. Here you have asked Manager to enter people for you, so when a card is read again after its owner has already finished, the new run is entered as another run of the same person — same name, same club, but not the same bib — in the class of the course they ran this time. Their first result is left as it was.</li><li><strong>Hire cards</strong> are the exception to both of the above. A <a href="./../running-the-event/hire-items">hire card</a> is lent to somebody new each time, so it is never named from the registry and a second read is a new, unnamed person rather than another run of the last one — unless the event <a href="#ignore-hire-cards">ignores hire cards</a>.</li></ul><p>Competitors entered this way count as entries on the day.</p><p>If a card cannot be entered — the event refused something it would have had to make — the banner says so, and the card waits at the desk as at any event.</p><h2 id="auto-create-courses-and-classes" tabindex="-1">Auto create courses and classes <a class="header-anchor" href="#auto-create-courses-and-classes" aria-label="Permalink to &quot;Auto create courses and classes&quot;">​</a></h2><p>With this on, a downloaded card that nobody is entered on, and whose punches fit no course, becomes a new course of those controls, in the order they were punched, with a class of its own. They are numbered: the first is <strong>Course 1</strong> with class <strong>1</strong>, the next <strong>Course 2</strong> with class <strong>2</strong>, and so on, skipping any number where a course called <strong>Course N</strong> or a class called <strong>N</strong> already exists; rename them on the Courses and Classes pages whenever you like.</p><ul><li><strong>What counts as fitting a course.</strong> A card is on a course if it is missing at most one of the course&#39;s controls, has at most one control the course doesn&#39;t, and shares at least one control with it. A skipped control, or a wrong control punched in place of the right one, is scored as a mis-punch on that course. One extra control on the way round doesn&#39;t count against the runner. A card that differs by two or more controls is a different course. Two courses that differ by only one control can&#39;t be told apart this way — import or draw them beforehand.</li><li><strong>A card with no finish punch never makes a course.</strong> It is somebody who retired, not a course. An EMIT card has no finish of its own — its last punch stands in for one — so enter the event&#39;s <strong>Finish codes</strong> (on the <a href="./create-event#radio-controls">Radio controls</a> tab of <strong>Event details</strong>) and a card whose last punch is not that unit is treated the same way.</li><li><strong>Existing courses are used.</strong> A card that fits a course already in the event — imported, drawn, or made from an earlier card — is scored on it. If no individual class uses that course yet, a class named after the course is made for it (numbered on, <strong>Orange 2</strong>, if a class called <strong>Orange</strong> already exists).</li><li><strong>Score and scatter events never make a course from a card.</strong> Their runners choose their own order, so the order one card was punched in is no course. Set up the score or scatter course beforehand instead — see <a href="./classes-and-courses#score-and-scatter-courses">Score and scatter courses</a>.</li><li>Every course made this way starts at the event&#39;s Start control and ends at its Finish; if the event has no Start or no Finish control, the missing one is made once and shared by every course.</li></ul><blockquote><p><strong>Watch the first card on each course.</strong> The first runner back defines the course. If they mis-punched badly, their course is wrong and the next runner on the real course makes a second one. Check the Courses page after the first few downloads, and delete a course that should not be there.</p></blockquote><h2 id="ignore-competitor-registry" tabindex="-1">Ignore competitor registry <a class="header-anchor" href="#ignore-competitor-registry" aria-label="Permalink to &quot;Ignore competitor registry&quot;">​</a></h2><p>With this on, nobody is suggested or named from the <a href="./../reference/competitor-registry">competitor registry</a> in this event. Nobody is suggested from it while you type a competitor in — at the console or at the entry desk — and nobody is named from it when a card is downloaded: no provisional name under an unknown card, no <strong>Assign to <em>name</em></strong> button, an automatically created competitor is named by their card number, and a card added from a <a href="./../running-the-event/station-memory#cards-nobody-is-entered-on">start or check unit&#39;s memory</a> is added as <strong>Unknown</strong>. Editing a competitor here doesn&#39;t update the registry either. Importing entries still uses it, and the <a href="./../after-the-event/changes-report">competitor changes report</a> can still write to it if you choose to.</p><p>Use it where cards are routinely borrowed — from a parent, a club box, a friend — so that whoever the registry has recorded against a card is as likely to be wrong as right. The registry itself is untouched, and every other event goes on using it.</p><h2 id="ignore-hire-cards" tabindex="-1">Ignore hire cards <a class="header-anchor" href="#ignore-hire-cards" aria-label="Permalink to &quot;Ignore hire cards&quot;">​</a></h2><p>With this on, the event treats no card as a hire card: the cards on your <a href="./../running-the-event/hire-items">hire card list</a> count as the runner&#39;s own. There is no prompt to collect the card at download, no card is marked as hired on the Competitors list or the Hire items page, and (with <strong>Auto create competitors on download</strong> on) a second run on one of them is entered as another run of the same person. Compasses, map boards and anything else you hire out are unaffected.</p><p>Use it where members borrow the same club card week after week. The hire card list itself is untouched, and every other event goes on using it.</p><h2 id="quick-name-entry-on-download" tabindex="-1">Quick name entry on download <a class="header-anchor" href="#quick-name-entry-on-download" aria-label="Permalink to &quot;Quick name entry on download&quot;">​</a></h2><p>With this on, a download for somebody nobody has named puts a <strong>New competitor</strong> field under the result banner with the cursor already in it, and a <strong>Class</strong> box beside it set to the class the card was matched to, or to the event&#39;s only class. Type the name and press <strong>Enter</strong>, or click <strong>Add competitor (Enter)</strong> — no dialog:</p><p><img src="'+i+'" alt="The Card downloads page after an unknown card was entered under its number, 8012345, with a + beside it: below the green OK banner, the New competitor field, the Class box and the Save name (Enter) button"></p><ol><li>The runner downloads their card.</li><li>You type their name and press <strong>Enter</strong>.</li></ol><p>If a mis-punch meant the card matched no course, or several classes run the course it matched, and the event has more than one class, the <strong>Class</strong> box is empty (and the banner says <strong>Not competing</strong>, or <strong>Unknown card</strong>). Nothing is saved until there is both a name and a class, so it is:</p><ol><li>Type the name, press <strong>Tab</strong> to move to the <strong>Class</strong> box.</li><li>Press <strong>↓</strong> (or <strong>↑</strong>) to step through the classes — or type a class&#39;s first letter to jump to it.</li><li>Press <strong>Enter</strong>. The runner is saved in that class and their card is checked again, so the banner shows their result on that course.</li></ol><p>You can change the class the same way when the match was wrong.</p><p>What <strong>Enter</strong> and the button do depends on the card:</p><ul><li><strong>A runner entered under their card number</strong> (with <strong>Auto create competitors on download</strong> on) is given the name. The button says <strong>Save name (Enter)</strong>.</li><li><strong>A card nobody is entered on</strong> is entered as a new competitor with that name, on that card, in the class in the <strong>Class</strong> box, and the download is theirs. The button says <strong>Add competitor (Enter)</strong>. If the card is in your <a href="./../reference/competitor-registry">competitor registry</a>, the field starts with the registry&#39;s name for it, so <strong>Enter</strong> alone accepts them — with their club and registry details, as <strong>Assign to <em>name</em></strong> would (see <a href="./../running-the-event/card-download#fast-fixes-right-after-a-download">Fast fixes right after a download</a>). Type over it and somebody new is entered instead.</li></ul><p>If the runner on an unknown card is already entered, don&#39;t type their name: that would enter them twice. On the dashboard&#39;s <strong>Download card</strong> tile, click <strong>Assign to existing competitor</strong> under the button, or <strong>Assign</strong> where the tile is too narrow for the full wording, and pick them. On <strong>Card downloads</strong>, use the search and <strong>Assign</strong> under <strong>Assign to existing</strong>.</p><p><img src="'+d+'" alt="The dashboard&#39;s Download card tile on an unknown card: the red Unknown card banner, the New competitor field and Class box, the Add competitor (Enter) button and, below it, Assign to existing competitor"></p><p>The last word you type is the family name and everything before it the given name, so <strong>Mary Jane Smith</strong> is <em>Mary Jane</em> / <em>Smith</em>. A name that doesn&#39;t split that way — <strong>Ian de Jongh</strong> — is put right on the competitor&#39;s <strong>Details</strong> tab.</p><p>Nobody has to type a name: the next card simply replaces the field, and a runner left unnamed keeps their card number and the <strong>+</strong> beside it. The field also won&#39;t take the cursor from you if you are already typing somewhere else — click into it in that case. On pages other than the dashboard and <strong>Card downloads</strong>, the download pop-up stays up until the name is typed or you close it.</p><h2 id="add-competitor-on-download-of-an-unknown-card" tabindex="-1">Add competitor on download of an unknown card <a class="header-anchor" href="#add-competitor-on-download-of-an-unknown-card" aria-label="Permalink to &quot;Add competitor on download of an unknown card&quot;">​</a></h2><p>With this on, a downloaded card that nobody is entered on opens the <strong>Add competitor</strong> dialog by itself, with the cursor already in the first name field. It is the same dialog the <strong>Add competitor</strong> button under an <strong>Unknown card</strong> banner opens — the card number filled in and locked, the class set to the one the card fits, and the person filled in from your <a href="./../reference/competitor-registry">competitor registry</a> when the card is in it. Type the runner in, pick a class if there isn&#39;t one, and save: they are entered and the download is theirs.</p><ul><li><strong>Only an unknown card.</strong> A card reused by somebody who already has a result, and a runner entered under their card number by <strong>Auto create competitors on download</strong>, don&#39;t open it.</li><li><strong>It won&#39;t interrupt you.</strong> It doesn&#39;t open while another dialog is open, or while you are typing somewhere else — use the <strong>Add competitor</strong> button then. Close it and it stays closed for that card.</li><li><strong>With Quick name entry on download</strong> also on, the name field under the banner is what you get, and the dialog doesn&#39;t open.</li></ul><h2 id="using-them-together" tabindex="-1">Using them together <a class="header-anchor" href="#using-them-together" aria-label="Permalink to &quot;Using them together&quot;">​</a></h2><p>Turn on the first two and an event needs nothing set up beforehand: the first card back makes the course and the class and gets a result, and every card after it is entered and placed as it is read. <a href="./create-event#duplicating-an-event"><strong>Duplicate event</strong></a> keeps them, so next week&#39;s training is set up already.</p><p>With only <strong>Auto create courses and classes</strong> on, a card nobody is entered on still waits for you at the desk as usual — the class of the course it fits, or the one just made for it, is what the <strong>Add competitor</strong> dialog is pre-filled with.</p><h2 id="making-them-the-default" tabindex="-1">Making them the default <a class="header-anchor" href="#making-them-the-default" aria-label="Permalink to &quot;Making them the default&quot;">​</a></h2><p>If most of your events are low-key, set the switches once in <strong>Settings → Low-key events</strong> (under <strong>System</strong>, below <strong>Event defaults</strong>). It has the same six switches, worded as on the tab. Every event you create from then on starts with them as set there — from <strong>New event</strong> and from an Eventor import alike.</p><ul><li><strong>Only new events.</strong> An event that already exists keeps its own switches; change them on its <strong>Low-key event</strong> tab. Turning a default off doesn&#39;t turn it off in any event already made.</li><li><strong>Every new event.</strong> A championship you create starts with them too, so turn them off on its <strong>Low-key event</strong> tab — an event that enters unknown cards by itself is not what a championship wants.</li><li>A <a href="./create-event#duplicating-an-event">duplicated</a> event, or one restored from a backup, keeps the switches it had rather than taking these.</li></ul><h2 id="related" tabindex="-1">Related <a class="header-anchor" href="#related" aria-label="Permalink to &quot;Related&quot;">​</a></h2><ul><li><a href="./../running-the-event/card-download">Downloading cards</a> — the download desk and the result banner</li><li><a href="./classes-and-courses">Classes and courses</a> — renaming and tidying up the courses and classes made from cards</li><li><a href="./../running-the-event/hire-items">Hire items</a> — the hire-card list that decides which cards are lent</li><li><a href="./../reference/competitor-registry">Competitor Registry</a> — where a card&#39;s owner is named from, unless the event ignores it</li><li><a href="./create-event#editing-event-details">Creating an event</a> — the <strong>Event details</strong> dialog where these settings live</li><li><a href="./../running-the-event/late-entries">Late entries</a> — entering people on the day at an ordinary event</li></ul>',46)])])}const b=n(h,[["render",c]]);export{y as __pageData,b as default};
